Get post with error handling

```python
def get_post_safe(post_id):
    """Get post with error handling"""
    url = f"https://jsonplaceholder.typicode.com/posts/{post_id}"

    try:
        response = requests.get(url, timeout=5)

        if response.status_code == 200:
            return {"success": True, "data": response.json()}
        elif response.status_code == 404:
            return {"success": False, "error": "Post not found"}
        else:
            return {"success": False, "error": f"Status code: {response.status_code}"}

    except requests.Timeout:
        return {"success": False, "error": "Request timed out"}
    except requests.RequestException as e:
        return {"success": False, "error": str(e)}

# Valid post
result = get_post_safe(1)
print(f"Valid post: {result['success']}")

# Invalid post (would be 404 but JSONPlaceholder returns empty)
result = get_post_safe(999999)
print(f"Invalid post: {result}")

